#ifdef GL_ES
precision mediump float;
#endif

#define MAX_PILLARS 16
#define PI 3.14159265359

float hash12(vec2 p)
{
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise2(vec2 p)
{
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);

  float a = hash12(i);
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));

  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

mat2 rotate2d(float radians)
{
  float s = sin(radians);
  float c = cos(radians);
  return mat2(c, -s, s, c);
}

void main()
{
  vec2 uv = isf_FragNormCoord.xy;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);

  vec2 p = uv - vec2(center, 0.5);
  p.x *= aspect;
  p = rotate2d(radians(angle)) * p;
  p.x /= aspect;
  vec2 ruv = p + vec2(center, 0.5);

  float count = floor(clamp(pillarCount, 1.0, float(MAX_PILLARS)) + 0.5);
  float pulse = mix(1.0, 0.5 + 0.5 * sin(TIME * pulseSpeed * 6.28318), pulseDepth);
  float verticalFade = exp(-max(ruv.y - floorPosition, 0.0) * heightFalloff);
  float bottomGlow = exp(-pow(max(ruv.y - floorPosition, 0.0) * 3.1, 2.0)) * floorBloom;

  vec3 color = vec3(backgroundLevel);
  float alphaMask = 0.0;

  for (int i = 0; i < MAX_PILLARS; ++i) {
    if (float(i) < count) {
      float fi = float(i);
      float centeredIndex = fi - (count - 1.0) * 0.5;
      float perPillarPhase = fi * 1.713 + 0.37;
      float drift = sin(TIME * driftSpeed + perPillarPhase) * driftAmount;
      float pillarX = center + centeredIndex * spacing + drift;

      float yTaper = 1.0 + pillarTaper * abs(ruv.y - floorPosition);
      float dx = abs(ruv.x - pillarX);
      float localCoreWidth = max(coreWidth * yTaper, 0.0001);
      float localGlowWidth = max(glowWidth * yTaper, 0.0001);

      float core = exp(-pow(dx / localCoreWidth, 2.0));
      float tightBlue = exp(-pow(dx / (localCoreWidth * 3.2), 2.0));
      float glow = exp(-pow(dx / localGlowWidth, edgeSoftness));
      float wideHalo = exp(-pow(dx / (localGlowWidth * 2.25), 1.35));
      float pillarNoise = 1.0 + (noise2(vec2(ruv.x * noiseScale, ruv.y * noiseScale * 0.25 + TIME * 3.0)) - 0.5) * noiseAmount;

      float pillarMask = (glow * glowBrightness + wideHalo * 0.22 + bottomGlow * glow) * verticalFade;
      float coreMask = (core * coreBrightness + tightBlue * 0.55) * verticalFade;
      float totalMask = (pillarMask + coreMask) * pillarBrightness * pulse * pillarNoise;

      vec3 pillarColor = glowColor.rgb * pillarMask * pillarBrightness * pulse;
      pillarColor += coreColor.rgb * coreMask * pillarBrightness * pulse;
      color += pillarColor * pillarNoise;
      alphaMask = max(alphaMask, clamp(totalMask, 0.0, 1.0));
    }
  }

  float dust = noise2(uv * noiseScale + vec2(TIME * 0.04, -TIME * 0.02));
  color += glowColor.rgb * dust * noiseAmount * 0.18;

  float vignetteMask = smoothstep(0.95, 0.18, distance(uv, vec2(0.5)));
  color *= mix(1.0, vignetteMask, vignette);

  color = max(color, vec3(0.0));
  color = pow(color, vec3(1.0 / gammaAdjust));

  gl_FragColor = vec4(color * opacity, alphaMask * opacity);
}
